2), '[]'::jsonb) FROM bounded_many) END FROM bounded_many) AS "__many_0" FROM index_entities AS "t0" WHERE "t0".tenant_id = '00000000-0000-0000-0000-000000000001'::uuid AND "t0".module_name = 'rustok-product' AND "t0".entity_name = 'product' AND "t0".schema_version = 1 AND "t0".schema_fingerprint = 'a70d4ed152578ded8f45a015d5dd5d2dd61b4e4c35330d834825ebb44ce14b5a' AND "t0".is_deleted = FALSE AND "t0".locale_key = $1 ORDER BY "t0".entity_id ASC LIMIT $3
